package com.college.hospitalmanagement;
import com.college.hospitalmanagement.dto.*;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class BedManagementService{
 private final WardRepository wards;private final RoomRepository rooms;private final BedRepository beds;private final BedAllocationRepository allocations;private final PatientRepository patients;
 public BedManagementService(WardRepository w,RoomRepository r,BedRepository b,BedAllocationRepository a,PatientRepository p){wards=w;rooms=r;beds=b;allocations=a;patients=p;}
 public List<WardResponseDTO> wards(){return wards.findAll().stream().map(this::ward).toList();}public WardResponseDTO ward(Long id){return ward(findWard(id));}@Transactional public WardResponseDTO createWard(WardRequestDTO r){uniqueWard(r,null);Ward w=new Ward();apply(r,w);return ward(wards.save(w));}@Transactional public WardResponseDTO updateWard(Long id,WardRequestDTO r){Ward w=findWard(id);uniqueWard(r,id);apply(r,w);return ward(wards.save(w));}@Transactional public void deleteWard(Long id){Ward w=findWard(id);if(!rooms.findByWardId(id).isEmpty()||beds.findByWardId(id).stream().anyMatch(b->allocations.existsByBedIdAndDischargeDateIsNull(b.getId())))throw new IllegalArgumentException("Ward cannot be deleted while it contains rooms or active allocations");wards.delete(w);}
 public List<RoomResponseDTO> rooms(){return rooms.findAll().stream().map(this::room).toList();}public RoomResponseDTO room(Long id){return room(findRoom(id));}@Transactional public RoomResponseDTO createRoom(RoomRequestDTO r){Room x=new Room();apply(r,x);return room(rooms.save(x));}@Transactional public RoomResponseDTO updateRoom(Long id,RoomRequestDTO r){Room x=findRoom(id);apply(r,x);return room(rooms.save(x));}@Transactional public void deleteRoom(Long id){Room x=findRoom(id);List<Bed> bs=beds.findByRoomId(id);if(!bs.isEmpty())throw new IllegalArgumentException("Room cannot be deleted while it contains beds");rooms.delete(x);}
 public List<BedResponseDTO> beds(){return beds.findAll().stream().map(this::bed).toList();}public BedResponseDTO bed(Long id){return bed(findBed(id));}@Transactional public BedResponseDTO createBed(BedRequestDTO r){Bed x=new Bed();apply(r,x);return bed(beds.save(x));}@Transactional public BedResponseDTO updateBed(Long id,BedRequestDTO r){Bed x=findBed(id);if(allocations.existsByBedIdAndDischargeDateIsNull(id)&&!"Occupied".equals(r.status()))throw new IllegalArgumentException("Occupied bed must be discharged before changing status");apply(r,x);return bed(beds.save(x));}@Transactional public void deleteBed(Long id){Bed x=findBed(id);if(allocations.existsByBedId(id))throw new IllegalArgumentException("Bed cannot be deleted while allocation history exists");beds.delete(x);}
 @Transactional public BedResponseDTO allocate(Long bedId,BedAllocationRequestDTO r){Bed b=beds.findLockedById(bedId).orElseThrow(()->new IllegalArgumentException("Bed not found: "+bedId));if(!"Available".equals(b.getStatus())||allocations.existsByBedIdAndDischargeDateIsNull(bedId))throw new IllegalArgumentException("Only available beds can be allocated");Patient p=patients.findById(r.patientId()).orElseThrow(()->new IllegalArgumentException("Patient not found: "+r.patientId()));if(allocations.existsByPatientIdAndDischargeDateIsNull(p.getId()))throw new IllegalArgumentException("Patient already has an active bed allocation");BedAllocation a=new BedAllocation();a.setBed(b);a.setPatient(p);a.setAdmissionDate(r.admissionDate());a.setNotes(r.notes());allocations.save(a);b.setStatus("Occupied");return bed(beds.save(b));}@Transactional public BedResponseDTO discharge(Long bedId){Bed b=beds.findLockedById(bedId).orElseThrow(()->new IllegalArgumentException("Bed not found: "+bedId));BedAllocation a=allocations.findByBedIdAndDischargeDateIsNull(bedId).stream().findFirst().orElseThrow(()->new IllegalArgumentException("No active allocation found for this bed"));a.setDischargeDate(LocalDate.now());allocations.save(a);b.setStatus("Available");return bed(beds.save(b));}
 private Ward findWard(Long id){return wards.findById(id).orElseThrow(()->new IllegalArgumentException("Ward not found: "+id));}private Room findRoom(Long id){return rooms.findById(id).orElseThrow(()->new IllegalArgumentException("Room not found: "+id));}private Bed findBed(Long id){return beds.findById(id).orElseThrow(()->new IllegalArgumentException("Bed not found: "+id));}private void uniqueWard(WardRequestDTO r,Long id){wards.findByCodeIgnoreCase(r.code()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("Ward code already exists");});wards.findByNameIgnoreCase(r.name()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("Ward name already exists");});}private void apply(WardRequestDTO r,Ward w){w.setName(r.name().trim());w.setCode(r.code().trim().toUpperCase());w.setFloor(r.floor());w.setWardType(r.wardType());w.setDescription(r.description());w.setStatus(r.status());}private void apply(RoomRequestDTO r,Room x){Ward w=findWard(r.wardId());rooms.findByWardIdAndRoomNumber(w.getId(),r.roomNumber().trim()).filter(y->!y.getId().equals(x.getId())).ifPresent(y->{throw new IllegalArgumentException("Room number already exists in this ward");});x.setRoomNumber(r.roomNumber().trim());x.setWard(w);x.setRoomType(r.roomType());x.setCapacity(r.capacity());x.setStatus(r.status());}private void apply(BedRequestDTO r,Bed x){Room room=findRoom(r.roomId());Ward ward=findWard(r.wardId());if(!room.getWard().getId().equals(ward.getId()))throw new IllegalArgumentException("Selected room does not belong to the ward");beds.findByRoomIdAndBedNumber(room.getId(),r.bedNumber().trim()).filter(y->!y.getId().equals(x.getId())).ifPresent(y->{throw new IllegalArgumentException("Bed number already exists in this room");});if(x.getId()==null&&beds.findByRoomId(room.getId()).size()>=room.getCapacity())throw new IllegalArgumentException("Room capacity has been reached");x.setBedNumber(r.bedNumber().trim());x.setWard(ward);x.setRoom(room);x.setBedType(r.bedType());x.setStatus(r.status());}
 private WardResponseDTO ward(Ward w){return new WardResponseDTO(w.getId(),w.getName(),w.getCode(),w.getFloor(),w.getWardType(),w.getDescription(),w.getStatus());}private RoomResponseDTO room(Room r){return new RoomResponseDTO(r.getId(),r.getRoomNumber(),r.getWard().getId(),r.getWard().getName(),r.getRoomType(),r.getCapacity(),r.getStatus());}private BedResponseDTO bed(Bed b){BedAllocation a=allocations.findByBedIdAndDischargeDateIsNull(b.getId()).stream().findFirst().orElse(null);return new BedResponseDTO(b.getId(),b.getBedNumber(),b.getWard().getId(),b.getWard().getName(),b.getRoom().getId(),b.getRoom().getRoomNumber(),b.getBedType(),b.getStatus(),a==null?null:a.getId(),a==null?null:a.getPatient().getId(),a==null?null:a.getPatient().getFullName());}}
